const _wh = $('Webhook SecOps').first().json || {};
const d = _wh.body || _wh;
const t = $('Tools SecOps').first().json || {};
const findings = [];

const ph = t.pihole || {};
const dns = t.unbound_dnssec || {};
const cs = t.crowdsec_ips || {};
if (ph.status !== 'ok') findings.push({level:'CRIT', text:'Pi-hole ' + (ph.status || 'sin datos')});
if (!dns.dnssec_ok) findings.push({level:'CRIT', text:'DNSSEC de Unbound no valida'});
if (cs.status && cs.status !== 'ok') findings.push({level:'WARN', text:'CrowdSec ' + cs.status});
if ((cs.decisions || 0) > 0) findings.push({level:'WARN', text:cs.decisions + ' decisiones IPS activas'});
if (!findings.length) findings.push({level:'OK', text:'Pi-hole, DNSSEC y CrowdSec operativos'});

const severity = findings.some(f => f.level === 'CRIT') ? 'CRIT'
  : findings.length ? 'WARN' : 'OK';
const evidence = JSON.stringify({pihole:t.pihole, dnssec:t.unbound_dnssec, crowdsec:t.crowdsec_ips, firewall:t.firewall_bouncer}).slice(0, 4500);
const prompt = `Eres Agent-SecOps, empleado especializado de HomeLab Corp.
Tu jefe es HomeLab-Director. Analiza esta evidencia en tiempo real y entrega un
informe ejecutivo de 3 a 5 líneas en español, con hallazgos concretos y
recomendaciones de solo lectura. No reinicies nada, no borres nada, no expongas
secretos. Si no hay problemas, dilo explícitamente.

EVIDENCIA:
${evidence}

HALLAZGOS DETERMINISTAS:
${JSON.stringify(findings)}
`;
return [{json: {
  employee: 'Agent-SecOps',
  severity,
  quality_score: 0.9,
  findings,
  evidence,
  prompt,
  directive: d.directive || '',
  task_id: d.task_id || null,
  round_id: d.round_id || null,
  tool_data: t
}}];

const a = $('Analizar SecOps').first().json || {};
const l = $('LLM SecOps').first().json || {};
const choices = l.choices || [];
const text = ((choices[0] && choices[0].message && choices[0].message.content) || '').trim();
return [{json: {
  employee: a.employee,
  severity: a.severity,
  quality_score: a.quality_score,
  summary: (text || a.summary || 'Sin hallazgos').slice(0, 2500),
  findings: a.findings || [],
  evidence: a.evidence || '',
  directive: a.directive || '',
  task_id: a.task_id || null,
  round_id: a.round_id || null
}}];

const r = $('Rendir cuentas SecOps').first().json || {};
const d = $('Redactar informe SecOps').first().json || {};
return [{json: {...d, report_id: r.report_id || null, ledger_ok: !!r.ok}}];
